import{_ as a,c as r,o as t,al as n}from"./chunks/framework.DM883ANZ.js";const b=JSON.parse('{"title":"MAVLink C Library #defines","description":"MAVLink C Library #defines — MAVLink message, enum and command reference.","frontmatter":{"outline":[2,3],"head":[["meta",{"property":"og:title","content":"MAVLink C Library #defines"}],["meta",{"property":"og:description","content":"MAVLink C Library #defines — MAVLink message, enum and command reference."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://mavlink.io/en/mavgen_c/defines.html"}],["link",{"rel":"canonical","href":"https://mavlink.io/en/mavgen_c/defines.html"}]]},"headers":[],"relativePath":"en/mavgen_c/defines.md","filePath":"en/mavgen_c/defines.md","lastUpdated":1795813857000}'),i={name:"en/mavgen_c/defines.md"};function o(l,e,d,s,h,_){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="mavlink-c-library-defines" tabindex="-1">MAVLink C Library #defines <a class="header-anchor" href="#mavlink-c-library-defines" aria-label="Permalink to &quot;MAVLink C Library #defines&quot;">​</a></h1><p>The C library generated by <em>mavgen</em> can be configured for different platforms and uses by defining the macros below. They must be defined before the library headers (e.g. <code>mavlink.h</code>) are included, usually in a single header that your code includes instead of the MAVLink headers.</p><p>Each entry links to where the library tests the macro, and to where <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h" target="_blank" rel="noreferrer">PX4</a> and <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h" target="_blank" rel="noreferrer">ArduPilot</a> set it (if they do).</p><h2 id="sending" tabindex="-1">Sending <a class="header-anchor" href="#sending" aria-label="Permalink to &quot;Sending&quot;">​</a></h2><h3 id="mavlink_use_convenience_functions" tabindex="-1">MAVLINK_USE_CONVENIENCE_FUNCTIONS <a class="header-anchor" href="#mavlink_use_convenience_functions" aria-label="Permalink to &quot;MAVLINK_USE_CONVENIENCE_FUNCTIONS {#mavlink_use_convenience_functions}&quot;">​</a></h3><p>Enables the <code>mavlink_msg_*_send()</code> functions in the generated message headers, and the helpers they use (<code>_mav_finalize_message_chan_send()</code>, <code>_mavlink_send_uart()</code>, <code>_mavlink_resend_uart()</code>). If defined you must also declare a global <code>mavlink_system_t mavlink_system</code> (the sending system and component IDs), and define either <code>MAVLINK_SEND_UART_BYTES</code> or <code>comm_send_ch()</code>. Leave it undefined if you pack and write out messages with your own code (see <a href="./../mavgen_c/#transmitting">Transmitting</a>).</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L405" target="_blank" rel="noreferrer">mavlink_helpers.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L47" target="_blank" rel="noreferrer">PX4</a>, <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L78" target="_blank" rel="noreferrer">ArduPilot</a>.</p><h3 id="mavlink_send_uart_bytes" tabindex="-1">MAVLINK_SEND_UART_BYTES <a class="header-anchor" href="#mavlink_send_uart_bytes" aria-label="Permalink to &quot;MAVLINK_SEND_UART_BYTES {#mavlink_send_uart_bytes}&quot;">​</a></h3><p><code>MAVLINK_SEND_UART_BYTES(chan, buf, len)</code> writes <code>len</code> bytes to the channel. If not defined, the library instead calls <code>comm_send_ch(chan, ch)</code> for each byte, which you must then provide.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L1262" target="_blank" rel="noreferrer">mavlink_helpers.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L50" target="_blank" rel="noreferrer">PX4</a>, <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L13" target="_blank" rel="noreferrer">ArduPilot</a>.</p><h3 id="mavlink_start_uart_send" tabindex="-1">MAVLINK_START_UART_SEND, MAVLINK_END_UART_SEND <a class="header-anchor" href="#mavlink_start_uart_send" aria-label="Permalink to &quot;MAVLINK_START_UART_SEND, MAVLINK_END_UART_SEND {#mavlink_start_uart_send}&quot;">​</a></h3><p><code>MAVLINK_START_UART_SEND(chan, length)</code> and <code>MAVLINK_END_UART_SEND(chan, length)</code> are called before and after each packet is written by the convenience functions (empty by default). For example, ArduPilot uses them to lock the channel while a packet is written.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/protocol.h#L28" target="_blank" rel="noreferrer">protocol.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L52-L53" target="_blank" rel="noreferrer">PX4</a>, <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L15-L16" target="_blank" rel="noreferrer">ArduPilot</a>.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><h3 id="mavlink_comm_num_buffers" tabindex="-1">MAVLINK_COMM_NUM_BUFFERS <a class="header-anchor" href="#mavlink_comm_num_buffers" aria-label="Permalink to &quot;MAVLINK_COMM_NUM_BUFFERS {#mavlink_comm_num_buffers}&quot;">​</a></h3><p>Maximum number of <a href="./../mavgen_c/#channels">channels</a>, and hence of the receive buffers and status structures allocated by the library (one of each per channel). By default this is 16 on Linux, Windows and macOS, and 4 on other platforms. You might reduce this to save memory (e.g. to <code>1</code> on a system with only one link). Using a channel number at or above this value will overrun the arrays. See also <a href="./../about/faq.html#how-can-i-further-reduce-the-generated-c-library-size">FAQ &gt; How can I further reduce the generated C library size?</a>.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_types.h#L190" target="_blank" rel="noreferrer">mavlink_types.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L59" target="_blank" rel="noreferrer">PX4</a>, <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L18-L28" target="_blank" rel="noreferrer">ArduPilot</a>.</p><h3 id="have_mavlink_channel_t" tabindex="-1">HAVE_MAVLINK_CHANNEL_T <a class="header-anchor" href="#have_mavlink_channel_t" aria-label="Permalink to &quot;HAVE_MAVLINK_CHANNEL_T {#have_mavlink_channel_t}&quot;">​</a></h3><p>The default <code>mavlink_channel_t</code> enum only defines <code>MAVLINK_COMM_0</code> to <code>MAVLINK_COMM_3</code>. Define this and declare your own <code>mavlink_channel_t</code> if you use more channels.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_types.h#L176" target="_blank" rel="noreferrer">mavlink_types.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L62-L71" target="_blank" rel="noreferrer">PX4</a>.</p><h3 id="mavlink_get_channel_status" tabindex="-1">MAVLINK_GET_CHANNEL_STATUS, MAVLINK_GET_CHANNEL_BUFFER <a class="header-anchor" href="#mavlink_get_channel_status" aria-label="Permalink to &quot;MAVLINK_GET_CHANNEL_STATUS, MAVLINK_GET_CHANNEL_BUFFER {#mavlink_get_channel_status}&quot;">​</a></h3><p>Define to provide your own <code>mavlink_get_channel_status(uint8_t chan)</code> and <code>mavlink_get_channel_buffer(uint8_t chan)</code>, instead of the library versions that return entries from <code>static</code> arrays. This allows you to keep the per-channel state wherever you like (the value of the macro is not used).</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L26-L56" target="_blank" rel="noreferrer">mavlink_helpers.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L55-L56" target="_blank" rel="noreferrer">PX4</a> (<a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_main.cpp#L156-L157" target="_blank" rel="noreferrer">implementation</a>), <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L32-L33" target="_blank" rel="noreferrer">ArduPilot</a> (<a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.cpp#L44-L66" target="_blank" rel="noreferrer">implementation</a>).</p><h3 id="mavlink_external_rx_status" tabindex="-1">MAVLINK_EXTERNAL_RX_STATUS, MAVLINK_EXTERNAL_RX_BUFFER <a class="header-anchor" href="#mavlink_external_rx_status" aria-label="Permalink to &quot;MAVLINK_EXTERNAL_RX_STATUS, MAVLINK_EXTERNAL_RX_BUFFER {#mavlink_external_rx_status}&quot;">​</a></h3><p>Keep the library versions of the functions above, but have them use arrays that you define, named <code>m_mavlink_status</code> (of <code>mavlink_status_t</code>) and <code>m_mavlink_buffer</code> (of <code>mavlink_message_t</code>), instead of <code>static</code> arrays inside the functions. These must be visible where <code>mavlink_helpers.h</code> is included (i.e. globals, or global pointers to memory that you allocate), with one entry per channel.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L26-L56" target="_blank" rel="noreferrer">mavlink_helpers.h</a>.</p><h2 id="signing" tabindex="-1">Signing <a class="header-anchor" href="#signing" aria-label="Permalink to &quot;Signing&quot;">​</a></h2><p>Signing is enabled for each channel at runtime, as described in <a href="./../mavgen_c/message_signing_c.html#enabling_signing_channel">C Message Signing</a>. These macros configure the signing implementation.</p><h3 id="mavlink_max_signing_streams" tabindex="-1">MAVLINK_MAX_SIGNING_STREAMS <a class="header-anchor" href="#mavlink_max_signing_streams" aria-label="Permalink to &quot;MAVLINK_MAX_SIGNING_STREAMS {#mavlink_max_signing_streams}&quot;">​</a></h3><p>Maximum number of signing streams (<code>(link ID, system ID, component ID)</code> tuples) tracked to detect replayed packets. Default 16. Signed packets from new streams are rejected once this limit is reached.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_types.h#L292" target="_blank" rel="noreferrer">mavlink_types.h</a>.</p><h3 id="mavlink_signing_timestamp_limit" tabindex="-1">MAVLINK_SIGNING_TIMESTAMP_LIMIT <a class="header-anchor" href="#mavlink_signing_timestamp_limit" aria-label="Permalink to &quot;MAVLINK_SIGNING_TIMESTAMP_LIMIT {#mavlink_signing_timestamp_limit}&quot;">​</a></h3><p>A signed packet from a new stream is rejected if its timestamp is more than this many seconds older than the local signing timestamp. Default 60.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L15" target="_blank" rel="noreferrer">mavlink_helpers.h</a>.</p><h3 id="mavlink_no_sign_packet" tabindex="-1">MAVLINK_NO_SIGN_PACKET <a class="header-anchor" href="#mavlink_no_sign_packet" aria-label="Permalink to &quot;MAVLINK_NO_SIGN_PACKET {#mavlink_no_sign_packet}&quot;">​</a></h3><p>Removes the code for signing outgoing packets (packets are never signed).</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L73" target="_blank" rel="noreferrer">mavlink_helpers.h</a>.</p><h3 id="mavlink_no_signature_check" tabindex="-1">MAVLINK_NO_SIGNATURE_CHECK <a class="header-anchor" href="#mavlink_no_signature_check" aria-label="Permalink to &quot;MAVLINK_NO_SIGNATURE_CHECK {#mavlink_no_signature_check}&quot;">​</a></h3><p>Removes the code for checking the signatures of incoming packets (signed packets are accepted without being verified).</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L185" target="_blank" rel="noreferrer">mavlink_helpers.h</a>.</p><h2 id="parsing" tabindex="-1">Parsing <a class="header-anchor" href="#parsing" aria-label="Permalink to &quot;Parsing&quot;">​</a></h2><h3 id="mavlink_check_message_length" tabindex="-1">MAVLINK_CHECK_MESSAGE_LENGTH <a class="header-anchor" href="#mavlink_check_message_length" aria-label="Permalink to &quot;MAVLINK_CHECK_MESSAGE_LENGTH {#mavlink_check_message_length}&quot;">​</a></h3><p>Rejects incoming messages with a payload length outside the minimum and maximum for their message ID. See <a href="./../mavgen_c/#additional-checks">Additional Checks</a>.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L860" target="_blank" rel="noreferrer">mavlink_helpers.h</a>.</p><h3 id="mavlink_get_msg_entry" tabindex="-1">MAVLINK_GET_MSG_ENTRY <a class="header-anchor" href="#mavlink_get_msg_entry" aria-label="Permalink to &quot;MAVLINK_GET_MSG_ENTRY {#mavlink_get_msg_entry}&quot;">​</a></h3><p>Define to provide your own <code>mavlink_get_msg_entry(uint32_t msgid)</code>, which returns the CRC extra, lengths, and target field offsets for a message ID. The library version does a bisection search of the dialect&#39;s <code>MAVLINK_MESSAGE_CRCS</code> table.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_helpers.h#L581" target="_blank" rel="noreferrer">mavlink_helpers.h</a>.</p><h2 id="code-size" tabindex="-1">Code Size <a class="header-anchor" href="#code-size" aria-label="Permalink to &quot;Code Size&quot;">​</a></h2><h3 id="mavlink_max_payload_len" tabindex="-1">MAVLINK_MAX_PAYLOAD_LEN <a class="header-anchor" href="#mavlink_max_payload_len" aria-label="Permalink to &quot;MAVLINK_MAX_PAYLOAD_LEN {#mavlink_max_payload_len}&quot;">​</a></h3><p>Maximum payload length (default 255 bytes). Reducing it reduces the size of <code>mavlink_message_t</code>, and hence of every channel buffer. It cannot be increased, because the payload length is stored in a <code>uint8_t</code>. Incoming packets with a longer payload are rejected, and the <code>mavlink_msg_*_send_buf()</code> functions are not generated for messages that are longer. For example, to reduce the maximum payload to the largest message in your dialect:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;mavlink/common/version.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MAVLINK_MAX_PAYLOAD_LEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MAVLINK_MAX_DIALECT_PAYLOAD_SIZE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;mavlink/common/mavlink.h&gt;</span></span></code></pre></div><p>See also <a href="./../about/faq.html#how-can-i-further-reduce-the-generated-c-library-size">FAQ &gt; How can I further reduce the generated C library size?</a>.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_types.h#L22" target="_blank" rel="noreferrer">mavlink_types.h</a>. Set by: <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L46-L48" target="_blank" rel="noreferrer">ArduPilot</a> (to 255).</p><h3 id="mavlink_separate_helpers" tabindex="-1">MAVLINK_SEPARATE_HELPERS <a class="header-anchor" href="#mavlink_separate_helpers" aria-label="Permalink to &quot;MAVLINK_SEPARATE_HELPERS {#mavlink_separate_helpers}&quot;">​</a></h3><p>Declares the helper functions in <code>mavlink_helpers.h</code> as ordinary functions, instead of defining them as <code>static inline</code> in every file that includes the library. You must then compile them once, normally by including <code>mavlink_helpers.h</code> in a single source file, or provide your own implementation.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/protocol.h#L157" target="_blank" rel="noreferrer">protocol.h</a>. Set by: <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L10" target="_blank" rel="noreferrer">ArduPilot</a> (<a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.cpp#L35-L42" target="_blank" rel="noreferrer">compiled in</a>).</p><h3 id="mavlink_no_conversion_helpers" tabindex="-1">MAVLINK_NO_CONVERSION_HELPERS <a class="header-anchor" href="#mavlink_no_conversion_helpers" aria-label="Permalink to &quot;MAVLINK_NO_CONVERSION_HELPERS {#mavlink_no_conversion_helpers}&quot;">​</a></h3><p>Omits the quaternion, Euler angle, and rotation matrix conversion functions (<code>mavlink_quaternion_to_euler()</code> and so on).</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_conversions.h#L3" target="_blank" rel="noreferrer">mavlink_conversions.h</a>. Set by: <a href="https://github.com/PX4/PX4-Autopilot/blob/f364b94f088165ebdc324e7edfae14767beb5bad/src/modules/mavlink/mavlink_bridge_header.h#L45" target="_blank" rel="noreferrer">PX4</a>, <a href="https://github.com/ArduPilot/ardupilot/blob/6034266b5abffd36fb4b89f0bf61fb6db8aed85d/libraries/GCS_MAVLink/GCS_MAVLink.h#L11" target="_blank" rel="noreferrer">ArduPilot</a>.</p><h3 id="mavlink_use_message_info" tabindex="-1">MAVLINK_USE_MESSAGE_INFO <a class="header-anchor" href="#mavlink_use_message_info" aria-label="Permalink to &quot;MAVLINK_USE_MESSAGE_INFO {#mavlink_use_message_info}&quot;">​</a></h3><p>Adds <code>mavlink_get_message_info()</code>, <code>mavlink_get_message_info_by_id()</code> and <code>mavlink_get_message_info_by_name()</code>, which return the name, type and offset of each field in a message. This is off by default because it adds a table describing every message in the dialect.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/mavlink_get_info.h#L3" target="_blank" rel="noreferrer">mavlink_get_info.h</a>.</p><h2 id="platform" tabindex="-1">Platform <a class="header-anchor" href="#platform" aria-label="Permalink to &quot;Platform&quot;">​</a></h2><h3 id="native_big_endian" tabindex="-1">NATIVE_BIG_ENDIAN <a class="header-anchor" href="#native_big_endian" aria-label="Permalink to &quot;NATIVE_BIG_ENDIAN {#native_big_endian}&quot;">​</a></h3><p>Define if using MAVLink on a system that is natively big-endian, so that fields are byte-swapped to and from the little-endian wire format.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/protocol.h#L10" target="_blank" rel="noreferrer">protocol.h</a>.</p><h2 id="wip-deprecated-superseded-diagnostics" tabindex="-1">WIP/Deprecated/Superseded Diagnostics <a class="header-anchor" href="#wip-deprecated-superseded-diagnostics" aria-label="Permalink to &quot;WIP/Deprecated/Superseded Diagnostics&quot;">​</a></h2><p><code>MAVLINK_WIP</code>, <code>MAVLINK_DEPRECATED</code>, <code>MAVLINK_SUPERSEDED</code>, <code>MAVLINK_ENUM_WIP</code>, <code>MAVLINK_ENUM_DEPRECATED</code>, <code>MAVLINK_ENUM_SUPERSEDED</code>, and (C++ 11 only) <code>MAVLINK_MSG_TYPE_WIP</code>, <code>MAVLINK_MSG_TYPE_DEPRECATED</code>, <code>MAVLINK_MSG_TYPE_SUPERSEDED</code> are empty by default. Define them as compiler attributes, such as <code>__attribute__((deprecated(&quot;...&quot;)))</code>, to get compile-time diagnostics where your code uses WIP, deprecated, or superseded messages and enum entries.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/protocol.h#L95-L112" target="_blank" rel="noreferrer">protocol.h</a>, <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/CPP11/include_v2.0/message.hpp#L79-L87" target="_blank" rel="noreferrer">message.hpp</a>.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><h3 id="mavlink_assert" tabindex="-1">MAVLINK_ASSERT <a class="header-anchor" href="#mavlink_assert" aria-label="Permalink to &quot;MAVLINK_ASSERT {#mavlink_assert}&quot;">​</a></h3><p><code>MAVLINK_ASSERT(x)</code> is the assertion used by the generated test suites (<code>testsuite.h</code>). Empty by default.</p><p>Source: <a href="https://github.com/ArduPilot/pymavlink/blob/4fd5b57831b047ea6f77469994be7d898505870e/generator/C/include_v2.0/protocol.h#L24" target="_blank" rel="noreferrer">protocol.h</a>.</p><h2 id="other-macros" tabindex="-1">Other Macros <a class="header-anchor" href="#other-macros" aria-label="Permalink to &quot;Other Macros&quot;">​</a></h2><p>Other macros in the headers, such as <code>MAVLINK_NEED_BYTE_SWAP</code>, <code>MAVLINK_ALIGNED_FIELDS</code>, <code>MAVLINK_CRC_EXTRA</code> and <code>MAVLINK_USE_CXX_NAMESPACE</code>, are set by the library or generated headers and should not be modified.</p>`,75)])])}const m=a(i,[["render",o]]);export{b as __pageData,m as default};
